1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.regex.Pattern;
6	
7	import net.officefloor.plugin.variable.Out;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
10	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
11	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
12	import org.springframework.web.bind.annotation.RequestBody;
13	
14	/**
15	 * First step of {@code POST /api/owners}. Rejects a create whose firstName, lastName,
16	 * address, city or telephone is missing or blank before {@link BuildOwner} maps the body,
17	 * so an incomplete request is a 400 listing each field rather than a persisted owner.
18	 * Also normalizes the telephone to E.164 form (see {@link TelephoneE164}), storing the E.164
19	 * value on the body and rejecting a number that cannot form a valid E.164 string. An optional
20	 * email, when present, must be a syntactically valid address and is stored lower-cased.
21	 * Publishes the validated body for the later steps.
22	 */
23	public class RequireOwnerFields {
24	
25	    /** Pragmatic syntactic check: one or more non-space/@ characters, an '@', a domain label,
26	     *  a dot, and a top-level label. Rejects inputs such as "not-an-email". */
27	    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
28	
29	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
30	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException {
31	        List<String> missing = new ArrayList<>();
32	        // Normalize the address up-front so the blank check below rejects an address that is
33	        // empty only after normalization (e.g. all-whitespace), and so the stored/returned value
34	        // and every later address comparison use the one canonical form.
35	        request.setAddress(AddressNormalizer.normalize(request.getAddress()));
36	        if (isBlank(request.getFirstName())) {
37	            missing.add("firstName");
38	        }
39	        if (isBlank(request.getLastName())) {
40	            missing.add("lastName");
41	        }
42	        if (isBlank(request.getAddress())) {
43	            missing.add("address");
44	        }
45	        if (isBlank(request.getCity())) {
46	            missing.add("city");
47	        }
48	        if (isBlank(request.getTelephone())) {
49	            missing.add("telephone");
50	        }
51	        if (!missing.isEmpty()) {
52	            throw new MissingOwnerFieldsException(missing);
53	        }
54	        request.setTelephone(TelephoneE164.normalize(request.getTelephone()));
55	        String email = request.getEmail();
56	        if (email != null && !email.isBlank()) {
57	            String normalized = email.trim().toLowerCase();
58	            if (!EMAIL.matcher(normalized).matches()) {
59	                throw new InvalidEmailException(email);
60	            }
61	            request.setEmail(normalized);
62	        }
63	        else {
64	            request.setEmail(null);
65	        }
66	        validated.set(request);
67	    }
68	
69	    private static boolean isBlank(String value) {
70	        return value == null || value.isBlank();
71	    }
72	}
