3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * Step of {@code POST /api/owners} that consolidates all duplicate detection into a single
11	 * check on the derived {@link OwnerIdentityKey}. Runs after {@link RequireOwnerFields} has
12	 * normalized the body. Rejects the create with 409 only when the new owner's WHOLE identityKey
13	 * (normalizedTelephone + '|' + email + '|' + householdId) equals an existing owner's, so a
14	 * difference in any single component — including the telephone — makes the two owners distinct
15	 * and both allowed.
16	 */
17	public class RequireUniqueIdentity {
18	
19	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
20	            throws DuplicateIdentityException {
21	        String identityKey = OwnerIdentityKey.forRequest(request);
22	        for (Owner existing : ownerRepository.findAll()) {
23	            if (identityKey.equals(OwnerIdentityKey.forOwner(existing))) {
24	                throw new DuplicateIdentityException(identityKey);
25	            }
26	        }
27	    }
28	}
