1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;
10	
11	/**
12	 * Step of {@code POST /api/owners} that rejects a create with 409 when the request's city already
13	 * contains {@value #CITY_CAPACITY} or more owners. The city is compared case-insensitively with
14	 * collapsed whitespace, the same canonical form used elsewhere in the pipeline.
15	 */
16	public class RequireCityCapacity {
17	
18	    /** Maximum number of owners a single city may contain. */
19	    private static final int CITY_CAPACITY = 50;
20	
21	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
22	            throws CityAtCapacityException {
23	        String city = normalize(request.getCity());
24	        int count = 0;
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (city.equals(normalize(existing.getCity()))) {
27	                count++;
28	            }
29	        }
30	        if (count >= CITY_CAPACITY) {
31	            throw new CityAtCapacityException(request.getCity());
32	        }
33	    }
34	
35	    /** Trim, collapse internal whitespace runs to a single space, and lower-case for comparison. */
36	    private static String normalize(String value) {
37	        if (value == null) {
38	            return "";
39	        }
40	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
41	    }
42	}
