1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	
6	import net.officefloor.plugin.variable.Out;
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	
10	/**
11	 * Step of {@code POST /api/owners} that fixes the EFFECTIVE registration date for the create —
12	 * the date supplied on the request, or the server's current date when none is supplied — and rolls
13	 * a weekend date forward to the next Monday so the registration date always falls on a business day.
14	 *
15	 * <p>Published as a variable so every later step works from the one adjusted date: the daily
16	 * create-limit counts owners per this business day, {@link BuildOwner} stores it, and any value
17	 * derived from it (such as the membership number's year segment) follows.
18	 */
19	public class DetermineRegistrationDate {
20	
21	    public void service(@Val OwnerFieldsDto request, Out<LocalDate> registrationDate) {
22	        LocalDate date = request.getRegistrationDate();
23	        if (date == null) {
24	            date = LocalDate.now();
25	        }
26	        registrationDate.set(toBusinessDay(date));
27	    }
28	
29	    /** Roll a Saturday or Sunday forward to the next Monday; a business day is unchanged. */
30	    static LocalDate toBusinessDay(LocalDate date) {
31	        DayOfWeek day = date.getDayOfWeek();
32	        if (day == DayOfWeek.SATURDAY) {
33	            return date.plusDays(2);
34	        }
35	        if (day == DayOfWeek.SUNDAY) {
36	            return date.plusDays(1);
37	        }
38	        return date;
39	    }
40	}
