3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.escalation.DailyOwnerLimitExceededException;
9	
10	/**
11	 * Step of {@code POST /api/owners} that rejects a create with 429 when {@value #DAILY_LIMIT} or
12	 * more owners have already been registered on the same business day (by {@code registrationDate}).
13	 * The day counted is the effective, business-day-adjusted registration date computed by
14	 * {@link DetermineRegistrationDate} — the very date the new owner would be stored with — so once
15	 * that day is full no further owner may be created for it.
16	 */
17	public class RequireDailyOwnerLimit {
18	
19	    /** Maximum number of owners that may be registered on a single day. */
20	    private static final int DAILY_LIMIT = 100;
21	
22	    public void service(@Val LocalDate registrationDate, OwnerRepository ownerRepository)
23	            throws DailyOwnerLimitExceededException {
24	        int count = 0;
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (registrationDate.equals(existing.getRegistrationDate())) {
27	                count++;
28	            }
29	        }
30	        if (count >= DAILY_LIMIT) {
31	            throw new DailyOwnerLimitExceededException(registrationDate);
32	        }
33	    }
34	}
