7	/**
8	 * Step of {@code POST /api/owners} that records how many owners belong to this owner's household
9	 * once this create completes. {@code householdSize} is the number of existing owners that already
10	 * share this owner's {@code householdId} plus one for the owner being created. Runs after
11	 * {@link AssignHouseholdId} (so the householdId is set) and before {@link SaveOwner} (so the owner
12	 * being created is not yet in the store and is counted exactly once via the {@code + 1}). Owners
13	 * with no householdId are a household of one.
14	 */
15	public class AssignHouseholdSize {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        String householdId = owner.getHouseholdId();
19	        int size = 1;
20	        if (householdId != null) {
21	            for (Owner existing : ownerRepository.findAll()) {
22	                if (householdId.equals(existing.getHouseholdId())) {
23	                    size++;
24	                }
25	            }
26	        }
27	        owner.setHouseholdSize(size);
28	    }
29	}
