1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	
6	/**
7	 * The single derived key that consolidates all duplicate detection for
8	 * {@code POST /api/owners}. An owner's {@code identityKey} is
9	 * {@code normalizedTelephone + '|' + (email or empty) + '|' + (householdId or empty)}; a
10	 * create is a duplicate — and rejected with 409 — only when a new owner's WHOLE identityKey
11	 * equals an existing owner's. Because the telephone is part of the key, two members of the
12	 * same household (same {@code householdId}) with different telephones have different keys and
13	 * are both allowed; only an exact full-key match collides.
14	 *
15	 * <p>Each component is normalized to the same canonical form the owner is stored with, so a
16	 * request and the owner it would duplicate produce identical keys regardless of input format:
17	 * the telephone to E.164 (see {@link TelephoneE164}), the email trimmed and lower-cased, and
18	 * the householdId derived exactly as {@link AssignHouseholdId} assigns it.
19	 */
20	public final class OwnerIdentityKey {
21	
22	    private OwnerIdentityKey() {
23	    }
24	
25	    /** The identityKey a create request would have once its owner is built. */
26	    public static String forRequest(OwnerFieldsDto request) {
27	        String householdId = Boolean.TRUE.equals(request.getSharesHousehold())
28	                ? AssignHouseholdId.householdId(request.getLastName(), request.getAddress())
29	                : null;
30	        return of(request.getTelephone(), request.getEmail(), householdId);
31	    }
32	
33	    /** The identityKey of an already-stored owner. */
34	    public static String forOwner(Owner owner) {
